const b=$input.first().json.body||{};if(b.secret!=='sv-mail-2026-09-17-Kq7'){throw new Error('bad secret');}if(b.mb!=='5'){throw new Error('mailbox 5 only');}
const re=/^[A-Za-z0-9._%+'-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/;
// 25 Sep (user): trail mails put EVERYONE on To, nobody on Cc. Accept a comma-separated list; every address must be valid and confirm_to must match the whole string.
const to=String(b.to||'').trim().toLowerCase().split(/\s*,\s*/).filter(Boolean).join(', ');
const parts=to.split(', ');if(!parts.length){throw new Error('bad to');}
for(const p of parts){const m=p.match(/<([^>]+)>\s*$/);const addr=(m?m[1]:p).trim();if(!re.test(addr)){throw new Error('bad to: '+p);}}
if(String(b.confirm_to||'').trim().toLowerCase().split(/\s*,\s*/).filter(Boolean).join(', ')!==to){throw new Error('confirm_to mismatch');}
if(!b.subject||!b.html){throw new Error('missing subject/html');}
const b64=Buffer.from(b.html,'utf8').toString('base64').replace(/(.{76})/g,'$1\r\n');
const mime=['From: Shradhaa Sidana <shradhaa@sidanaventures.com>','To: '+to,(b.cc?'Cc: '+b.cc:'X-Sidana: 1'),'Subject: =?UTF-8?B?'+Buffer.from(b.subject,'utf8').toString('base64')+'?=','MIME-Version: 1.0','Content-Type: text/html; charset="UTF-8"','Content-Transfer-Encoding: base64','',b64].join('\r\n');
const raw=Buffer.from(mime,'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
if(b.dry!==false){throw new Error('DRY OK | to='+to+' | cc='+(b.cc||'')+' | subject='+b.subject+' | htmlLen='+b.html.length);}
return [{json:{to:to,subject:b.subject,raw:raw}}];
